import java.util.*;

public class Main {
    static final long MOD = 1000000007;

    public static long fastPow(long base, long exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    static class DisjointSet {
        int[] parent;
        int[] rank;
        int totalComponents;

        public DisjointSet(int n) {
            parent = new int[n];
            rank = new int[n];
            totalComponents = n;
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        public int find(int u) {
            if (parent[u] != u) {
                parent[u] = find(parent[u]);
            }
            return parent[u];
        }

        public void merge(int u, int v) {
            u = find(u);
            v = find(v);
            if (u != v) {
                if (rank[u] < rank[v]) {
                    int temp = u;
                    u = v;
                    v = temp;
                }
                parent[v] = u;
                if (rank[u] == rank[v]) {
                    rank[u]++;
                }
                totalComponents--;
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();

        boolean[] visited = new boolean[(int) p];
        DisjointSet ds = new DisjointSet((int) p);

        for (long i = 0; i < p; i++) {
            for (long j = i; !visited[(int) j]; j = (j * k) % p) {
                visited[(int) j] = true;
                ds.merge((int) i, (int) j);
            }
        }

        int c = ds.totalComponents;
        if (k != 1) {
            c--;
        }
        System.out.println(fastPow(p, c));
        sc.close();
    }
}
